 function live(on){active=on;e('record-live').hidden=!on;e('record-start').hidden=on;e('record-stop').hidden=!on;clearInterval(timer);if(on)timer=setInterval(()=>e('record-live-label').textContent='● Đang ghi · '+Math.floor((Date.now()-start)/1000)+' giây',1000)}
 function cleanStreams(){for(const s of streams)s.getTracks().forEach(t=>t.stop());streams=[];const v=e('web-camera-preview');v.srcObject=null;v.hidden=true;e('studio').append(v)}
 function preview(stream){const v=e('web-camera-preview');v.srcObject=stream;v.hidden=false;v.classList.add('camera-bubble');(e('reader').open?e('reader'):document.body).append(v);v.play().catch(()=>{});let drag;v.onpointerdown=event=>{drag={x:event.clientX,y:event.clientY,left:v.offsetLeft,top:v.offsetTop};v.setPointerCapture(event.pointerId)};v.onpointermove=event=>{if(!drag)return;v.style.right='auto';v.style.bottom='auto';v.style.left=Math.max(0,Math.min(innerWidth-90,drag.left+event.clientX-drag.x))+'px';v.style.top=Math.max(100,Math.min(innerHeight-140,drag.top+event.clientY-drag.y))+'px'};v.onpointerup=()=>drag=null}
 async function refresh(){try{const result=native?await call('recordings'):local;const items=Array.isArray(result)?result:result.items||[];const list=e('recordings-list');list.replaceChildren();for(const item of items){const box=document.createElement('div');box.className='recording-item';const title=document.createElement('strong');title.textContent=item.name||'Bản ghi';const info=document.createElement('small');info.textContent=((item.bytes||0)/1024/1024).toFixed(2)+' MB';box.append(title,info);for(const kind of ['save','share']){const button=document.createElement('button');button.textContent=kind==='save'?'Lưu tệp':'Chia sẻ';button.addEventListener('click',async()=>{try{if(native){await call(kind==='save'?'recordSave':'recordShare',{name:item.name})}else{const blob=item.blob;if(kind==='share'&&navigator.share&&navigator.canShare?.({files:[new File([blob],item.name,{type:blob.type})]}))await navigator.share({files:[new File([blob],item.name,{type:blob.type})]});else{const a=document.createElement('a');a.href=item.url;a.download=item.name;a.click()}}}catch(error){toast(error.message)}});box.append(button)}list.append(box)}if(!items.length)list.textContent='Chưa có bản ghi trên thiết bị.'}catch(error){status(error.message)}}
