 if(period<0||diff[period]>.28)return null;const left=diff[period-1],mid=diff[period],right=diff[period+1],denom=2*(2*mid-right-left),shift=Number.isFinite(denom)&&Math.abs(denom)>.00001?(right-left)/denom:0;
