  const n=score.notes[i];if(![.5,1,2,4].includes(n.beats)||!(n.midi===null||Number.isInteger(n.midi)&&n.midi>=48&&n.midi<=84)||beats%4+n.beats>4)throw Error('Nốt hoặc nhịp không hợp lệ.');
